mapper.select:
WITH hY AS ( /* 최신 확정(Y) */ SELECT yrt_id FROM ( SELECT h.yrt_id FROM yrt_header h WHERE h.emp_id = (SELECT e.emp_id FROM emp e WHERE e.emp_no = #{empId, jdbcType=VARCHAR}) AND h.base_year = #{baseYear, jdbcType=NUMERIC} AND h.confirm_yn = 'Y' ORDER BY h.created_at DESC ) WHERE ROWNUM = 1 ), hN AS ( /* 최신 미확정(N) */ SELECT yrt_id FROM ( SELECT h.yrt_id FROM yrt_header h WHERE h.emp_id = (SELECT e.emp_id FROM emp e WHERE e.emp_no = #{empId, jdbcType=VARCHAR}) AND h.base_year = #{baseYear, jdbcType=NUMERIC} AND h.confirm_yn = 'N' ORDER BY h.created_at DESC ) WHERE ROWNUM = 1 ), chosen AS ( /* 우선순위: 명시 yrtId > 최신 Y */ SELECT COALESCE(#{yrtId, jdbcType=NUMERIC}, (SELECT yrt_id FROM hY)) AS yrt_id FROM dual ) SELECT it.category AS itemClass, it.item_name AS itemName,
/* 금액 우선순위: yrtId가 있으면 그 실행(dS) > Y(dY), 없으면 Y(dY) */ CASE WHEN #{yrtId, jdbcType=NUMERIC} IS NOT NULL THEN NVL(dS.amount, NVL(dY.amount, 0)) ELSE NVL(dY.amount, 0) END AS amount,
/* 예상금액: 선택 실행 expected_amount 없으면 amount → Y로 fallback */ CASE WHEN #{yrtId, jdbcType=NUMERIC} IS NOT NULL THEN NVL(dS.expected_amount, NVL(dS.amount, NVL(dY.amount, 0))) ELSE NVL(dY.expected_amount, NVL(dY.amount, 0)) END AS expectedAmount,
/* 헤더 메타: yrtId가 있으면 그 실행 헤더(hS), 없으면 Y(hY2) */ COALESCE(hS.tax_apply_type, hY2.tax_apply_type) AS taxApplyType, COALESCE(hS.tax_apply_result,hY2.tax_apply_result)AS taxApplyResult, COALESCE(hS.confirm_yn, hY2.confirm_yn) AS confirmYn
FROM yrt_item it
/* 확정(Y) 디테일/헤더 */ LEFT JOIN hY ON 1=1 LEFT JOIN yrt_detail dY ON dY.yrt_item_id = it.yrt_item_id AND dY.yrt_id = hY.yrt_id LEFT JOIN yrt_header hY2 ON hY2.yrt_id = hY.yrt_id
/* 선택 실행(yrtId 명시 or 최신 Y) 디테일/헤더 */ LEFT JOIN chosen c ON 1=1 LEFT JOIN yrt_detail dS ON dS.yrt_item_id = it.yrt_item_id AND dS.yrt_id = c.yrt_id LEFT JOIN yrt_header hS ON hS.yrt_id = c.yrt_id
ORDER BY it.category, it.item_name

mapper.delete:
BEGIN
  DELETE FROM yrt_detail
   WHERE yrt_id IN (
     SELECT yrt_id FROM yrt_header
      WHERE emp_id = (SELECT e.emp_id FROM emp e WHERE e.emp_no = #{empId, jdbcType=VARCHAR})
        AND base_year = #{baseYear, jdbcType=NUMERIC}
        AND confirm_yn = 'N'
   );

  DELETE FROM yrt_result_total
   WHERE yrt_id IN (
     SELECT yrt_id FROM yrt_header
      WHERE emp_id = (SELECT e.emp_id FROM emp e WHERE e.emp_no = #{empId, jdbcType=VARCHAR})
        AND base_year = #{baseYear, jdbcType=NUMERIC}
        AND confirm_yn = 'N'
   );

  DELETE FROM yrt_header
   WHERE emp_id = (SELECT e.emp_id FROM emp e WHERE e.emp_no = #{empId, jdbcType=VARCHAR})
     AND base_year = #{baseYear, jdbcType=NUMERIC}
     AND confirm_yn = 'N';
END;

BEGIN
  DELETE FROM yrt_detail       WHERE yrt_id = #{yrtId, jdbcType=NUMERIC};
  DELETE FROM yrt_result_total WHERE yrt_id = #{yrtId, jdbcType=NUMERIC};
  DELETE FROM yrt_header       WHERE yrt_id = #{yrtId, jdbcType=NUMERIC} AND confirm_yn = 'N';
END;
